import {defaultRules,buildEvents,addDays} from './schedule.js';
const TODAY='2026-10-13';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=value=>Number(value||0).toLocaleString('ko-KR');
const short=date=>date?`${Number(date.slice(5,7))}.${Number(date.slice(8,10))}`:'미정';
const seed=()=>[
 {id:'PO-001',number:'BJ-2026-1012',customer:'범진전자',type:'domestic',model:'BCM-24A',quantity:10000,receivedDate:'2026-10-12',shipDate:'2026-10-20',dueDate:'2026-10-21',eta:'',file:'범진전자_PO_1012.pdf'},
 {id:'PO-002',number:'CV-2026-1013',customer:'CHEMTRO VINA',type:'overseas',model:'CH-88V',quantity:4000,receivedDate:TODAY,shipDate:'',dueDate:'',eta:'2026-10-23',file:'CHEMTRO_PO_1013.xlsx'},
 {id:'PO-003',number:'SR-2026-1009',customer:'세림모터스',type:'domestic',model:'SM-402',quantity:2500,receivedDate:'2026-10-09',shipDate:'2026-10-15',dueDate:'2026-10-16',eta:'',file:'세림모터스_발주서.pdf'},
 {id:'PO-004',number:'VN-2026-1012',customer:'VINA TECH',type:'overseas',model:'VT-210',quantity:1800,receivedDate:'2026-10-12',shipDate:'',dueDate:'',eta:'',file:'VINA_TECH_PO.xlsx'}
];
let orders=seed(),rules=structuredClone(defaultRules),done=new Set(),view='calendar',type='all',search='',month='2026-10',selected=TODAY,files=[],queueIndex=0,nextId=5;
const app=document.querySelector('#app');
const allEvents=()=>orders.flatMap(order=>buildEvents(order,rules));
const filteredOrders=()=>orders.filter(order=>(type==='all'||order.type===type)&&(!search||`${order.number} ${order.customer} ${order.model}`.toLowerCase().includes(search.toLowerCase())));
const filteredEvents=()=>allEvents().filter(event=>filteredOrders().some(order=>order.id===event.orderId));
const badge=order=>`<span class="badge ${order.type}">${order.type==='domestic'?'국내':'해외'}</span>`;
function render(){
 const today=allEvents().filter(event=>event.date===TODAY&&!done.has(event.eventId));
 const undated=allEvents().filter(event=>!event.date);
 app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#"><span class="logo">P</span><span>PO 관리<small>ORDER CALENDAR</small></span></a><p class="nav-label">WORKSPACE</p><button data-view="calendar" class="nav ${view==='calendar'?'active':''}"><span>▦</span>업무 달력</button><button data-view="orders" class="nav ${view==='orders'?'active':''}"><span>▤</span>PO 목록<span class="nav-count">${orders.length}</span></button><button data-action="rules" class="nav"><span>⚙</span>자동 일정 규칙</button><div class="sidebar-note"><span class="green-dot"></span>UI 목업<small>샘플 데이터로 흐름을 확인합니다.</small><button data-action="reset">데모 초기화 ↺</button></div></aside>
 <div class="workspace"><header class="topbar"><span class="crumb">워크스페이스 <span>/</span> <strong>${view==='calendar'?'업무 달력':'PO 목록'}</strong></span><div><span class="demo-label">미리보기</span><span class="user">김</span></div></header><main><section class="page-head"><div><p class="eyebrow">PO MANAGEMENT</p><h1>${view==='calendar'?'PO와 업무를 한눈에':'PO 목록'}</h1><p class="subtitle">파일을 등록하면 필요한 업무가 날짜에 맞춰 달력에 표시됩니다.</p></div><button class="btn primary" data-action="upload"><span>＋</span> PO 파일 등록</button></section>
 <div class="summary"><article><span>관리 중인 PO</span><strong>${orders.length}<small>건</small></strong><p>국내 ${orders.filter(o=>o.type==='domestic').length} · 해외 ${orders.filter(o=>o.type==='overseas').length}</p></article><article><span>오늘 할 일</span><strong>${today.length}<small>건</small></strong><p>10월 13일 화요일</p></article><article><span>7일 이내 일정</span><strong>${allEvents().filter(e=>e.date>TODAY&&e.date<=addDays(TODAY,7)&&!done.has(e.eventId)).length}<small>건</small></strong><p>미완료 업무 기준</p></article><article class="pending-summary"><span>날짜 확인 필요</span><strong>${undated.length}<small>건</small></strong><p>ETA 입력 시 자동 배치</p></article></div>
 <div class="filters"><div class="segments">${[['all','전체'],['domestic','국내'],['overseas','해외']].map(([value,label])=>`<button data-type="${value}" class="${type===value?'selected':''}" aria-pressed="${type===value}">${label}</button>`).join('')}</div><label class="search"><span>⌕</span><input type="search" placeholder="고객사, PO 번호, 모델 검색" aria-label="PO 검색" value="${esc(search)}"></label><div class="legend"><span><i class="blue-dot"></i>국내</span><span><i class="teal-dot"></i>해외</span></div></div>
 ${view==='calendar'?renderCalendar():renderOrders()}
 <footer class="page-footer">국내 일정은 출고예정일 기준 · 해외 일정은 수령일과 ETA 기준 <button data-action="rules">일정 생성 규칙 보기 →</button></footer></main></div></div>`;
}
function renderCalendar(){
 const [year,m]=month.split('-').map(Number),first=new Date(Date.UTC(year,m-1,1)),start=addDays(`${month}-01`,-first.getUTCDay());
 const count=new Date(Date.UTC(year,m,0)).getUTCDate(),rows=Math.ceil((first.getUTCDay()+count)/7),events=filteredEvents();
 const days=Array.from({length:rows*7},(_,i)=>{const date=addDays(start,i),daily=events.filter(e=>e.date===date);return `<div class="day ${date.slice(0,7)!==month?'outside':''} ${date===selected?'chosen':''}" data-date="${date}"><button class="day-number ${date===TODAY?'today':''}" data-date="${date}" aria-label="${date} 일정 보기">${Number(date.slice(8))}</button><div class="day-events">${daily.slice(0,3).map(event=>`<button class="event ${event.type} ${done.has(event.eventId)?'done':''}" data-event="${event.eventId}" title="${esc(event.customer+' · '+event.title)}"><span>${done.has(event.eventId)?'✓':event.id.endsWith('due')?'●':'•'}</span><div><strong>${esc(event.title)}</strong><small>${esc(event.customer)}</small></div></button>`).join('')}${daily.length>3?`<button class="more" data-date="${date}">+${daily.length-3}개 더 보기</button>`:''}</div></div>`;});
 const selectedEvents=events.filter(event=>event.date===selected);
 return `<div class="calendar-layout"><section class="calendar-card"><div class="calendar-toolbar"><div class="month-title"><h2>${year}년 ${m}월</h2><span>월간</span></div><div class="month-controls"><button aria-label="이전 달" data-month="-1">‹</button><button class="today-button" data-action="today">오늘</button><button aria-label="다음 달" data-month="1">›</button></div></div><div class="weekdays">${['일','월','화','수','목','금','토'].map((d,i)=>`<span class="${i===0?'sun':i===6?'sat':''}">${d}</span>`).join('')}</div><div class="calendar-grid">${days.join('')}</div></section><aside class="agenda"><div class="agenda-header"><p class="eyebrow">DAILY AGENDA</p><h2>${Number(selected.slice(5,7))}월 ${Number(selected.slice(8))}일 <span>${['일','월','화','수','목','금','토'][new Date(selected+'T00:00:00Z').getUTCDay()]}요일</span></h2><p>선택한 날짜의 일정 ${selectedEvents.length}건</p></div><div class="agenda-list">${selectedEvents.length?selectedEvents.map(taskRow).join(''):'<div class="empty-agenda"><span>✓</span><strong>등록된 일정이 없습니다</strong><p>다른 날짜를 선택해 확인하세요.</p></div>'}</div><div class="undated"><h3><span class="amber-dot"></span>날짜 미정 <span>${events.filter(e=>!e.date).length}</span></h3>${events.filter(e=>!e.date).map(event=>`<button data-order="${event.orderId}"><strong>${esc(event.customer)}</strong><span>${esc(event.title)}<small>ETA를 입력하면 날짜가 지정됩니다.</small></span><b>›</b></button>`).join('')||'<p class="muted">모든 일정의 날짜가 정해졌습니다.</p>'}</div><div class="tip"><span>✦</span><p>일정의 고객사를 누르면 PO 정보를 수정할 수 있습니다. 변경된 날짜는 달력에 바로 반영됩니다.</p></div></aside></div>`;
}
function taskRow(event){const complete=done.has(event.eventId);return `<article class="task-row ${complete?'complete':''}"><button class="check ${complete?'checked':''}" data-check="${event.eventId}" aria-label="${esc(event.title)} ${complete?'완료 취소':'완료 처리'}" aria-pressed="${complete}">${complete?'✓':''}</button><div><span class="task-type ${event.type}">${event.type==='domestic'?'국내':'해외'} · ${esc(event.basis)}</span><button class="task-title" data-event="${event.eventId}">${esc(event.title)}</button><button class="task-customer" data-order="${event.orderId}">${esc(event.customer)} ↗</button></div></article>`;}
function renderOrders(){return `<section class="orders-card"><div class="orders-head"><h2>등록된 PO <span>${filteredOrders().length}</span></h2><small>등록 후 날짜를 수정하면 일정도 갱신됩니다.</small></div><div class="table-scroll"><table><thead><tr><th>고객사 / PO 번호</th><th>구분</th><th>모델 / 수량</th><th>PO 수령일</th><th>출고예정일</th><th>납기일 / ETA</th><th>업무 완료</th><th></th></tr></thead><tbody>${filteredOrders().map(order=>{const tasks=buildEvents(order,rules);return `<tr><td><button class="order-title" data-order="${order.id}">${esc(order.customer)}</button><small>${esc(order.number)}</small></td><td>${badge(order)}</td><td>${esc(order.model)}<small>${n(order.quantity)} EA</small></td><td>${short(order.receivedDate)}</td><td>${order.type==='domestic'?short(order.shipDate):'—'}</td><td>${short(order.type==='domestic'?order.dueDate:order.eta)}<small>${order.type==='domestic'?'납기일':'ETA'}</small></td><td><span class="progress-count">${tasks.filter(e=>done.has(e.eventId)).length} / ${tasks.length}</span></td><td><button class="row-arrow" data-order="${order.id}" aria-label="${esc(order.customer)} 상세">›</button></td></tr>`;}).join('')||'<tr><td colspan="8" class="empty">검색 결과가 없습니다.</td></tr>'}</tbody></table></div></section>`;}
let dialogReturn;
function modal(title,body,submitLabel,onSubmit){
 document.querySelector('dialog')?.remove();dialogReturn=document.activeElement;
 const dialog=document.createElement('dialog');dialog.innerHTML=`<form><header><div><p class="eyebrow">PO MANAGEMENT</p><h2>${esc(title)}</h2></div><button type="button" class="close" data-close aria-label="닫기">×</button></header><div class="modal-body">${body}<p class="error" role="alert"></p></div><footer><button type="button" class="btn secondary" data-close>닫기</button>${onSubmit?`<button class="btn primary" type="submit">${esc(submitLabel)}</button>`:''}</footer></form>`;dialog.setAttribute('aria-label',title);document.body.append(dialog);
 const close=()=>{dialog.close();dialog.remove();dialogReturn?.isConnected&&dialogReturn.focus();};dialog.querySelectorAll('[data-close]').forEach(button=>button.onclick=close);dialog.oncancel=e=>{e.preventDefault();close();};
 dialog.querySelector('form').onsubmit=e=>{e.preventDefault();try{if(onSubmit(Object.fromEntries(new FormData(e.currentTarget)))!==false)close();}catch(error){dialog.querySelector('.error').textContent=error.message;}};dialog.showModal();return dialog;
}
function toast(message){const notice=document.querySelector('#notice');notice.textContent=message;notice.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>notice.classList.remove('visible'),3200);}
function upload(){files=[];queueIndex=0;const dialog=modal('PO 파일 등록',`<p class="modal-intro">엑셀 또는 PDF를 등록하고 인식 결과를 확인하세요.</p><label class="drop-zone"><span class="upload-symbol">↥</span><strong>파일을 끌어 놓거나 클릭해서 선택</strong><small>Excel (.xlsx, .xls) · PDF · 여러 파일 선택 가능</small><input id="po-files" type="file" multiple accept=".xlsx,.xls,.pdf" aria-label="PO 파일 선택"></label><div id="file-list"></div><div class="mock-note"><span>i</span><p>이 목업에서는 파일명·형식을 읽고 <strong>샘플 인식 결과</strong>를 표시합니다. 실제 Excel 분석·PDF OCR은 아직 연결되지 않았습니다.</p></div><button type="button" class="demo-file" data-action="sample-upload">파일 없이 샘플로 체험하기 →</button>`,'샘플 인식 결과 확인',()=>{if(!files.length)throw new Error('파일을 선택하거나 샘플로 체험해 주세요.');setTimeout(()=>reviewFile(),0);return true;});
 const receive=items=>{files=[...items].filter(file=>/\.(xlsx|xls|pdf)$/i.test(file.name));if(!files.length){toast('Excel 또는 PDF 파일을 선택하세요.');return;}dialog.querySelector('#file-list').innerHTML=files.map(file=>`<div class="file-row"><span class="file-icon">${/pdf$/i.test(file.name)?'PDF':'XLS'}</span><span><strong>${esc(file.name)}</strong><small>${n(Math.ceil(file.size/1024))} KB · 인식 대기</small></span><b>✓</b></div>`).join('');};
 dialog.querySelector('#po-files').onchange=e=>receive(e.target.files);const zone=dialog.querySelector('.drop-zone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragging');};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragging');receive(e.dataTransfer.files);};
}
function fields(order){return `<div class="form-grid"><label>구분<select name="type" id="order-type"><option value="domestic" ${order.type==='domestic'?'selected':''}>국내 PO</option><option value="overseas" ${order.type==='overseas'?'selected':''}>해외 PO</option></select></label><label>고객사<input name="customer" required value="${esc(order.customer)}"></label><label>PO 번호<input name="number" required value="${esc(order.number)}"></label><label>모델<input name="model" required value="${esc(order.model)}"></label><label>수량 (EA)<input name="quantity" type="number" required min="1" value="${order.quantity}"></label><label>PO 수령일<input name="receivedDate" type="date" required value="${order.receivedDate}"></label><label data-domestic>출고예정일<input name="shipDate" type="date" value="${order.shipDate}"></label><label data-domestic>납기일<input name="dueDate" type="date" value="${order.dueDate}"></label><label data-overseas>ETA <span class="optional">미정이면 비워두기</span><input name="eta" type="date" value="${order.eta}"></label></div><div id="schedule-preview"></div>`;}
function wireFields(dialog,base){
 const update=()=>{const values=Object.fromEntries(new FormData(dialog.querySelector('form'))),order={...base,...values};dialog.querySelectorAll('[data-domestic]').forEach(e=>{e.hidden=order.type!=='domestic';e.querySelector('input').required=order.type==='domestic';});dialog.querySelectorAll('[data-overseas]').forEach(e=>e.hidden=order.type!=='overseas');try{dialog.querySelector('#schedule-preview').innerHTML=`<div class="schedule-preview"><h3>자동 생성될 일정 <span>${order.type==='domestic'?3:4}건</span></h3>${buildEvents(order,rules).map(event=>`<div><span class="preview-date ${!event.date?'undated-date':''}">${event.date?event.date:'날짜 미정'}</span><span>${esc(event.title)}<small>${esc(event.basis)}</small></span></div>`).join('')}</div>`;}catch{dialog.querySelector('#schedule-preview').innerHTML='<p class="muted">기준 날짜를 입력하면 일정이 표시됩니다.</p>';}};
 dialog.querySelector('.form-grid').oninput=update;dialog.querySelector('.form-grid').onchange=update;update();
}
function validate(values){if(!values.customer.trim()||!values.number.trim()||!values.model.trim()||!Number.isFinite(Number(values.quantity))||Number(values.quantity)<=0)throw new Error('고객사·PO 번호·모델·수량을 확인하세요.');if(orders.some(o=>o.number===values.number&&o.id!==values.id))throw new Error('동일한 PO 번호가 이미 등록되어 있습니다.');buildEvents(values,rules);return {...values,quantity:Number(values.quantity)};}
function reviewFile(){const file=files[queueIndex];const order={id:'pending',type:'domestic',number:`PO-20261013-${String(nextId).padStart(3,'0')}`,customer:'샘플 고객사',model:'MODEL-100',quantity:2000,receivedDate:TODAY,shipDate:'2026-10-20',dueDate:'2026-10-21',eta:'2026-10-23',file:file.name};const dialog=modal('인식 결과 확인',`<div class="review-file"><span class="file-icon">${/pdf$/i.test(file.name)?'PDF':'XLS'}</span><div><strong>${esc(file.name)}</strong><small>파일 ${queueIndex+1} / ${files.length} · 샘플 인식 결과</small></div><span class="review-status">확인 필요</span></div><p class="modal-intro">아래 값은 예시입니다. 실제 PO 내용으로 수정하고 등록하세요.</p>${fields(order)}`,'확인 후 PO 등록',values=>{const data=validate({...values,id:order.id});orders.push({...data,id:`PO-${String(nextId++).padStart(3,'0')}`,file:file.name});render();toast(`PO 등록 완료 · 일정 ${data.type==='domestic'?3:4}건 생성`);queueIndex++;if(queueIndex<files.length)setTimeout(reviewFile,0);return true;});wireFields(dialog,order);}
function openOrder(id){const order=orders.find(order=>order.id===id);if(!order)return;const dialog=modal(`${order.customer} · PO 정보`,`${badge(order)}<p class="source-file">원본: ${esc(order.file)}</p>${fields(order)}`,'저장 및 일정 갱신',values=>{Object.assign(order,validate({...values,id:order.id}));render();toast('PO 정보와 달력 일정을 갱신했습니다.');return true;});wireFields(dialog,order);}
function openEvent(eventId){const event=allEvents().find(e=>e.eventId===eventId);if(!event)return;const order=orders.find(o=>o.id===event.orderId);modal(event.title,`<div class="event-detail">${badge(order)}<h3>${esc(order.customer)}</h3><p>${esc(order.number)} · ${esc(order.model)} · ${n(order.quantity)} EA</p><dl><dt>일정 날짜</dt><dd>${event.date||'날짜 미정'}</dd><dt>자동 생성 기준</dt><dd>${esc(event.basis)}</dd><dt>처리 상태</dt><dd>${done.has(eventId)?'완료':'할 일'}</dd></dl><p class="muted">기준 날짜는 PO 정보에서 수정할 수 있습니다.</p></div>`,done.has(eventId)?'완료 취소':'업무 완료',()=>{toggleDone(eventId);return true;});}
function toggleDone(eventId){done.has(eventId)?done.delete(eventId):done.add(eventId);render();toast('업무 상태를 변경했습니다.');}
function ruleDialog(){modal('자동 일정 규칙',`<p class="modal-intro">업무명은 예시입니다. 실제 사용하는 업무명으로 바꿀 수 있습니다.</p><div class="rule-list">${rules.map(rule=>`<label><span class="badge ${rule.type}">${rule.type==='domestic'?'국내':'해외'}</span><span>${esc(rule.basis)}</span><input name="${rule.id}" value="${esc(rule.title)}" required aria-label="${esc(rule.basis)} 업무명"></label>`).join('')}</div><div class="rule-note"><strong>날짜 계산 기준</strong><p>국내: 출고예정일 −2일 / −1일, 납기일<br>해외: 수령일, 수령일 당일, 다음 주 화요일, ETA +1일<br>주는 월요일부터 일요일까지입니다. 공휴일·주말도 날짜 그대로 표시합니다.</p></div>`,'업무명 저장',values=>{rules=rules.map(rule=>({...rule,title:values[rule.id].trim()}));render();toast('달력의 업무명을 갱신했습니다.');return true;});}
document.addEventListener('click',e=>{
 const target=e.target.closest('button,[data-date]');if(!target)return;
 if(target.dataset.view){view=target.dataset.view;render();}
 if(target.dataset.type){type=target.dataset.type;render();}
 if(target.dataset.month){const [y,m]=month.split('-').map(Number);const date=new Date(Date.UTC(y,m-1+Number(target.dataset.month),1));month=date.toISOString().slice(0,7);render();}
 if(target.dataset.date){selected=target.dataset.date;render();}
 if(target.dataset.event)openEvent(target.dataset.event);
 if(target.dataset.order)openOrder(target.dataset.order);
 if(target.dataset.check)toggleDone(target.dataset.check);
 const action=target.dataset.action;
 if(action==='upload')upload();if(action==='rules')ruleDialog();if(action==='today'){month=TODAY.slice(0,7);selected=TODAY;render();}
 if(action==='reset'){orders=seed();done=new Set();rules=structuredClone(defaultRules);month=TODAY.slice(0,7);selected=TODAY;nextId=5;render();toast('샘플 데이터를 초기화했습니다.');}
 if(action==='sample-upload'){files=[{name:'샘플_PO.xlsx',size:24000}];queueIndex=0;reviewFile();}
});
document.addEventListener('input',e=>{if(e.target.matches('.search input')){search=e.target.value;const cursor=e.target.selectionStart;render();const input=document.querySelector('.search input');input.focus();input.setSelectionRange(cursor,cursor);}});
render();
